window.RA_DATA.lines = [
  { id: "de-pp-1", book_id: "pied-piper-of-hamelin", place_ids: ["de-hamelin-pied-piper-house"], location: "Stanza 1", location_zh: "第 1 节", text_en: "Hamelin Town's in Brunswick,\nBy famous Hanover city;\nThe river Weser, deep and wide,\nWashes its wall on the southern side;\nA pleasanter spot you never spied;\nBut, when begins my ditty,\nAlmost five hundred years ago,\nTo see the townsfolk suffer so\nFrom vermin, was a pity.", highlight_en: ["Hamelin Town"], text_zh: "哈默尔恩镇在不伦瑞克，\n靠着有名的汉诺威城；\n威悉河又深又宽，\n冲刷着它南边的城墙；\n你再也找不到更可爱的地方；\n可是，在我这首歌开头的时候，\n差不多五百年以前，\n看着镇上的人被\n老鼠折磨成那样，真叫人可怜。", highlight_zh: ["哈默尔恩镇"], translation: "original", status: "draft", checked: "Project Gutenberg #18343, 2026-11-17" },
  { id: "de-gr-1", book_id: "grimms-fairy-tales", place_ids: ["de-bremen-town-musicians"], location: "The Bremen Town Musicians", location_zh: "《不来梅的城市乐手》", text_orig: "Es hatte ein Mann einen Esel, der schon lange Jahre die Säcke unverdrossen zur Mühle getragen hatte, dessen Kräfte aber nun zu Ende gingen, so daß er zur Arbeit immer untauglicher ward. Da dachte der Herr daran, ihn aus dem Futter zu schaffen, aber der Esel merkte, daß kein guter Wind wehte, lief fort und machte sich auf den Weg nach Bremen; dort, meinte er, könnte er ja Stadtmusikant werden.", highlight_orig: ["Bremen"], text_en: "A certain man had a donkey, which had carried the corn-sacks to the mill indefatigably for many a long year; but his strength was going, and he was growing more and more unfit for work. Then his master began to consider how he might best save his keep; but the donkey, seeing that no good wind was blowing, ran away and set out on the road to Bremen. \"There,\" he thought, \"I can surely be town-musician.\"", highlight_en: ["Bremen"], text_zh: "有个人养了一头驴，多年来不知疲倦地把一袋袋粮食驮到磨坊去；可它的力气用尽了，越来越干不动活。主人便盘算着省下它的草料；驴子觉出风向不好，就跑了，上路往不来梅去，心想：“在那里，我总能当个城市乐手。”", highlight_zh: ["不来梅"], translation: "Margaret Hunt (1884)", status: "draft", checked: "Project Gutenberg #77905 and #5314, 2026-11-17" },
  { id: "de-gr-2", book_id: "grimms-fairy-tales", place_ids: ["de-sababurg"], location: "Little Briar-Rose", location_zh: "《荆棘公主》", text_orig: "Rings um das Schloß aber begann eine Dornenhecke zu wachsen, die jedes Jahr höher ward und endlich das ganze Schloß umzog und darüber hinauswuchs, daß gar nichts mehr davon zu sehen war, selbst nicht die Fahne auf dem Dach.", highlight_orig: ["das Schloß"], text_en: "But round about the castle there began to grow a hedge of thorns, which every year became higher, and at last grew close up round the castle and all over it, so that there was nothing of it to be seen, not even the flag upon the roof.", highlight_en: ["the castle"], text_zh: "城堡四周却长起了一道荆棘篱笆，一年比一年高，最后把整座城堡围了个严实，还盖过了它，什么都看不见了，连屋顶上的旗子也看不见了。", highlight_zh: ["城堡"], translation: "Margaret Hunt (1884)", status: "draft", checked: "Project Gutenberg #77905 and #5314, 2026-11-17" },
  { id: "de-pt-1", book_id: "poetry-and-truth", place_ids: ["de-goethe-house-frankfurt"], location: "Book 1", location_zh: "第 1 卷", text_en: "On the 28th of August, 1749, at mid-day, as the clock struck twelve, I came into the world, at Frankfort-on-the-Maine.", highlight_en: ["Frankfort-on-the-Maine"], text_zh: "1749 年 8 月 28 日正午，钟敲十二下的时候，我在美因河畔法兰克福来到了这个世界。", highlight_zh: ["美因河畔法兰克福"], translation: "John Oxenford (1848)", status: "draft", checked: "Project Gutenberg #52654, 2026-11-17" },
  { id: "de-pt-2", book_id: "poetry-and-truth", place_ids: ["de-brennender-berg"], location: "Book 10", location_zh: "第 10 卷", text_en: "We entered into a chasm and found ourselves in the region of the Burning Mountain. A strong smell of sulphur surrounded us; one side of the cavity was almost red-hot, covered with reddish stone burnt white; thick fumes arose from the crevices, and we felt the heat of the ground through our strong boot-soles.", highlight_en: ["the Burning Mountain"], text_zh: "我们走进一道裂谷，便到了那座燃烧的山的地界。浓烈的硫磺味包围着我们；坑的一边几乎烧得通红，盖满了烧成白色的红石头；浓烟从裂缝里冒出来，隔着结实的靴底，我们都能感到地面的热气。", highlight_zh: ["燃烧的山"], translation: "John Oxenford (1848)", status: "draft", checked: "Project Gutenberg #52654, 2026-11-17" },
  { id: "de-fa-1", book_id: "faust", place_ids: ["de-auerbachs-keller"], location: "Part 1, Auerbach's Cellar in Leipzig", location_zh: "第一部《莱比锡的奥尔巴赫地窖》", text_orig: "Wahrhaftig, du hast recht! Mein Leipzig lob ich mir!\nEs ist ein klein Paris, und bildet seine Leute.", highlight_orig: ["Leipzig"], text_en: "You've verily hit the truth! Leipzig to me is dear:\nParis in miniature, how it refines its people!", highlight_en: ["Leipzig"], text_zh: "你说得一点不错！我就爱我的莱比锡！\n它是个小巴黎，把人都调教得文雅。", highlight_zh: ["莱比锡"], translation: "Bayard Taylor (1870)", status: "draft", checked: "Project Gutenberg #2229 and #14591, 2026-11-17" },
  { id: "de-bud-1", book_id: "buddenbrooks", place_ids: ["de-buddenbrookhaus"], location: "Part 1, Chapter 1", location_zh: "第一部第 1 章", text_orig: "Man saß im »Landschaftszimmer«, im ersten Stockwerk des weitläufigen alten Hauses in der Mengstraße, das die Firma Johann Buddenbrook vor einiger Zeit käuflich erworben hatte und das die Familie noch nicht lange bewohnte.", highlight_orig: ["Hauses in der Mengstraße"], text_en: "They were sitting in the 'landscape room' on the first floor of the rambling old house in the Mengstraße, which the firm of Johann Buddenbrook had bought some time before and which the family had not lived in for long.", highlight_en: ["the rambling old house in the Mengstraße"], text_zh: "一家人坐在“风景厅”里，这是孟街那座宽敞的老房子二楼的一间屋子；约翰·布登勃洛克商行不久前买下了这座房子，一家人搬进来还没有多久。", highlight_zh: ["孟街那座宽敞的老房子"], translation: "own", status: "draft", checked: "Project Gutenberg #34811, 2026-11-17" },
  { id: "de-hei-1", book_id: "germany-a-winters-tale", place_ids: ["de-hamburg-rathausmarkt"], location: "Caput 21", location_zh: "第 21 章", text_orig: "Die Stadt, zur Hälfte abgebrannt,\nWird aufgebaut allmählich;\nWie 'n Pudel, der halb geschoren ist,\nSieht Hamburg aus, trübselig.", highlight_orig: ["Hamburg"], text_en: "They bit by bit are building again\nThe hapless half-burnt city;\nLike a half-shorn poodle Hamburg now looks,\nAn object to waken one's pity.", highlight_en: ["Hamburg"], text_zh: "这座烧掉了一半的城市，\n正一点一点地重建；\n汉堡看上去像一只剪了一半毛的卷毛狗，\n叫人看了心酸。", highlight_zh: ["汉堡"], translation: "Edgar Alfred Bowring (1859)", status: "draft", checked: "Project Gutenberg #6079 and #52882, 2026-11-17" },
  { id: "de-lor-1", book_id: "book-of-songs", place_ids: ["de-loreley"], location: "The Homecoming, 2 (The Lorelei)", location_zh: "《还乡集》第 2 首《罗蕾莱》", text_orig: "Ich weiß nicht, was soll es bedeuten,\nDaß ich so traurig bin;\nEin Märchen aus alten Zeiten,\nDas kommt mir nicht aus dem Sinn.\n\nDie Luft ist kühl und es dunkelt,\nUnd ruhig fließt der Rhein;\nDer Gipfel des Berges funkelt\nIm Abendsonnenschein.", highlight_orig: ["der Rhein"], text_en: "In vain would I seek to discover\nWhy sad and mournful am I;\nMy thoughts without ceasing brood over\nA tale of the times gone by.\n\nThe air is cool, and it darkleth,\nAnd calmly flows the Rhine;\nThe peak of the mountain sparkleth,\nWhile evening's sun doth shine.", highlight_en: ["the Rhine"], text_zh: "我不知道这意味着什么，\n我竟如此悲伤；\n一个古老的传说，\n总萦绕在我心上。\n\n空气清凉，暮色渐浓，\n莱茵河静静流淌；\n山顶在夕阳的余晖里\n闪闪发光。", highlight_zh: ["莱茵河"], translation: "Edgar Alfred Bowring (1859)", status: "draft", checked: "Project Gutenberg #3498 and #52882, 2026-11-17" },
  { id: "de-ta-1", book_id: "a-tramp-abroad", place_ids: ["de-loreley"], location: "Chapter 16", location_zh: "第 16 章", text_en: "Germany is rich in folk-songs, and the words and airs of several of them are peculiarly beautiful—but \"The Lorelei\" is the people's favorite. I could not endure it at first, but by and by it began to take hold of me, and now there is no tune which I like so well.", highlight_en: ["\"The Lorelei\""], text_zh: "德国的民歌很多，其中好几首词和曲都美得出奇，而《罗蕾莱》是老百姓最喜欢的一首。我起初受不了它，可渐渐地它抓住了我，现在再没有哪支曲子是我这么喜欢的了。", highlight_zh: ["《罗蕾莱》"], translation: "original", status: "draft", checked: "Project Gutenberg #119, 2026-11-17" },
  { id: "de-ta-2", book_id: "a-tramp-abroad", place_ids: ["de-heidelberg-castle"], location: "Chapter 2", location_zh: "第 2 章", text_en: "One thinks Heidelberg by day—with its surroundings—is the last possibility of the beautiful; but when he sees Heidelberg by night, a fallen Milky Way, with that glittering railway constellation pinned to the border, he requires time to consider upon the verdict.", highlight_en: ["Heidelberg"], text_zh: "人们以为白天的海德堡，连同它的周遭，已经美到了极致；可等他看见夜里的海德堡——一条坠落的银河，边上还别着一串闪闪发亮的铁路星座——他就需要时间好好想想，才能下结论了。", highlight_zh: ["海德堡"], translation: "original", status: "draft", checked: "Project Gutenberg #119, 2026-11-17" },
  { id: "de-sf-s1", kind: "scene", book_id: "slaughterhouse-five", place_ids: ["de-dresden-slaughterhouse"], location: "Chapter 8", location_zh: "第 8 章", text_en: "Billy Pilgrim and the other American prisoners are locked up in Schlachthof-fünf, a slaughterhouse in Dresden; on the night of the firebombing they shelter in a meat locker deep underground, and when they climb out the next day the city looks like the surface of the moon.", text_zh: "比利·皮尔格林和其他美军战俘被关在德累斯顿一座屠宰场——“五号屠场”；大轰炸那一夜，他们躲在深深的地下冻肉库里，第二天爬出来时，整座城市就像月球表面。", highlight_en: ["Dresden"], highlight_zh: ["德累斯顿"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Slaughterhouse-Five" },
  { id: "de-gb-s1", kind: "scene", book_id: "goodbye-to-berlin", place_ids: ["de-nollendorfplatz"], location: "A Berlin Diary (Autumn 1930)", location_zh: "《柏林日记（1930 年秋）》", text_en: "The narrator, a young Englishman named Christopher, looks out from his room in a shabby, once-grand street near the Nollendorfplatz and resolves to record what he sees with the detachment of a camera; his landlady Fräulein Schroeder and the cabaret singer Sally Bowles soon fill his pages.", text_zh: "叙述者、一个叫克里斯托弗的英国年轻人，从诺伦多夫广场附近一条破旧却曾经体面的街上的出租屋窗口往外看，决心像一架相机那样冷静地记下眼前的一切；房东施罗德小姐和歌厅女郎萨莉·鲍尔斯很快就占满了他的纸页。", highlight_en: ["the Nollendorfplatz"], highlight_zh: ["诺伦多夫广场"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Goodbye_to_Berlin" },
  { id: "de-emil-s1", kind: "scene", book_id: "emil-and-the-detectives", place_ids: ["de-nollendorfplatz"], location: "Chapters 7–10", location_zh: "第 7–10 章", text_en: "Robbed of his money on the train to Berlin, Emil follows the thief in the bowler hat across the city to a hotel on the Nollendorfplatz, where a gang of Berlin children led by Gustav with the horn joins him to keep watch all night.", text_zh: "埃米尔在去柏林的火车上被偷了钱，他跟着那个戴圆顶礼帽的小偷穿过大半个城，一直跟到诺伦多夫广场边的一家旅馆；拿着汽车喇叭的古斯塔夫带着一帮柏林孩子加入进来，陪他守了一整夜。", highlight_en: ["the Nollendorfplatz"], highlight_zh: ["诺伦多夫广场"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Emil_and_the_Detectives" },
  { id: "de-ba-s1", kind: "scene", book_id: "berlin-alexanderplatz", place_ids: ["de-alexanderplatz"], location: "Book 1", location_zh: "第一卷", text_en: "Released from Tegel prison in 1927, Franz Biberkopf rides the tram back into the roar of central Berlin, panics at the crowds, and swears that from now on he will stay decent; the Alexanderplatz, dug up for the new underground, is where his new life begins and keeps going wrong.", text_zh: "1927 年，弗兰茨·毕伯科普夫从泰格尔监狱获释，坐电车回到柏林市中心的喧嚣里，被人潮吓得发慌，发誓从此做个正派人；正为修地铁而挖得乱七八糟的亚历山大广场，就是他新生活开始、又一再出错的地方。", highlight_en: ["the Alexanderplatz"], highlight_zh: ["亚历山大广场"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Berlin_Alexanderplatz" },
  { id: "de-btw-s1", kind: "scene", book_id: "beneath-the-wheel", place_ids: ["de-hesse-calw"], location: "Chapter 1", location_zh: "第 1 章", text_en: "Hans Giebenrath, the brightest boy in a little Black Forest town, gives up fishing and his free afternoons to cram for the state examination that will send him to the seminary at Maulbronn, while the whole town watches and his father brags.", text_zh: "汉斯·吉本拉特是黑森林边一座小城里最聪明的孩子，为了考上去毛尔布龙神学院的州考，他放弃了钓鱼和所有的空闲下午，全城的人都看着他，父亲则到处夸耀。", highlight_en: ["a little Black Forest town"], highlight_zh: ["黑森林边一座小城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Beneath_the_Wheel" },
  { id: "de-wer-1", book_id: "the-sorrows-of-young-werther", place_ids: ["de-lottehaus-wetzlar"], location: "Book 1, letter of 16 June", location_zh: "第一部，6 月 16 日的信", text_orig: "Ich ging durch den Hof nach dem wohlgebauten Hause, und da ich die vorliegenden Treppen hinaufgestiegen war und in die Tür trat, fiel mir das reizendste Schauspiel in die Augen, das ich je gesehen habe. in dem Vorsaale wimmelten sechs Kinder von eilf zu zwei Jahren um ein Mädchen von schöner Gestalt, mittlerer Größe, die ein simples weißes Kleid, mit blaßroten Schleifen an Arm und Brust, anhatte.", highlight_orig: ["dem wohlgebauten Hause"], text_en: "I walked across the court to a well-built house, and, ascending the flight of steps in front, opened the door, and saw before me the most charming spectacle I had ever witnessed. Six children, from eleven to two years old, were running about the hall, and surrounding a lady of middle height, with a lovely figure, dressed in a robe of simple white, trimmed with pink ribbons.", highlight_en: ["a well-built house"], text_zh: "我穿过院子，走向一座造得很好的房子，登上门前的台阶，推门进去，眼前是我见过的最迷人的景象：六个从十一岁到两岁的孩子，在前厅里围着一个身材匀称、中等个子的姑娘团团转，她穿一件朴素的白衣裙，袖口和胸前系着淡红色的缎带。", highlight_zh: ["一座造得很好的房子"], translation: "R. Dillon Boylan (1854)", status: "draft", checked: "Project Gutenberg #2407 and #2527, 2026-11-17" },
  { id: "de-fa-2", book_id: "faust", place_ids: ["de-brocken"], location: "Part 1, Walpurgis Night", location_zh: "第一部《瓦尔普吉斯之夜》", text_orig: "Die Hexen zu dem Brocken ziehn,\nDie Stoppel ist gelb, die Saat ist grün.\nDort sammelt sich der große Hauf,\nHerr Urian sitzt oben auf.", highlight_orig: ["Brocken"], text_en: "The witches ride to the Brocken's top,\nThe stubble is yellow, and green the crop.\nThere gathers the crowd for carnival:\nSir Urian sits over all.", highlight_en: ["the Brocken"], text_zh: "女巫们骑向布罗肯山顶，\n麦茬已黄，新苗正青。\n一大群都在那里聚会，\n乌利安老爷高坐在上头。", highlight_zh: ["布罗肯山"], translation: "Bayard Taylor (1870)", status: "draft", checked: "Project Gutenberg #2229 and #14591, 2026-11-17" },
  { id: "de-st-1", book_id: "the-stechlin", place_ids: ["de-stechlinsee"], location: "Chapter 1", location_zh: "第 1 章", text_orig: "Im Norden der Grafschaft Ruppin, hart an der mecklenburgischen Grenze, zieht sich von dem Städtchen Gransee bis nach Rheinsberg hin (und noch darüber hinaus) eine mehrere Meilen lange Seenkette durch eine menschenarme, nur hie und da mit ein paar alten Dörfern, sonst aber ausschließlich mit Förstereien, Glas- und Teeröfen besetzte Waldung.", highlight_orig: ["eine mehrere Meilen lange Seenkette"], text_en: "In the north of the county of Ruppin, close to the Mecklenburg border, a chain of lakes several miles long runs from the little town of Gransee to Rheinsberg (and on beyond it) through woodland that has few people in it, only an old village here and there and otherwise nothing but forest lodges, glassworks and tar kilns.", highlight_en: ["a chain of lakes several miles long"], text_zh: "鲁平伯爵领的北部，紧挨着梅克伦堡的边界，从小城格兰塞到莱茵斯贝格（还要再往外去），有一串好几英里长的湖泊穿过一片人烟稀少的林地，林子里只零星有几座老村庄，其余全是林务所、玻璃作坊和焦油窑。", highlight_zh: ["一串好几英里长的湖泊"], translation: "own", status: "draft", checked: "Project Gutenberg #53628, 2026-11-17" },
  { id: "de-kh-1", book_id: "michael-kohlhaas", place_ids: ["de-kleist-grave"], location: "Opening", location_zh: "开篇", text_orig: "An den Ufern der Havel lebte, um die Mitte des sechzehnten Jahrhunderts, ein Roßhändler, namens Michael Kohlhaas, Sohn eines Schulmeisters, einer der rechtschaffensten zugleich und entsetzlichsten Menschen seiner Zeit.", highlight_orig: ["Ufern der Havel"], text_en: "On the banks of the Havel, around the middle of the sixteenth century, there lived a horse dealer named Michael Kohlhaas, a schoolmaster's son, one of the most upright and at the same time most terrible men of his age.", highlight_en: ["the banks of the Havel"], text_zh: "十六世纪中叶，哈弗尔河畔住着一个马贩子，名叫米夏埃尔·科尔哈斯，是一位教书先生的儿子，他是那个时代最正直、同时也最可怕的人之一。", highlight_zh: ["哈弗尔河畔"], translation: "own", status: "draft", checked: "Project Gutenberg #6645, 2026-11-17" },
  { id: "de-nib-1", book_id: "the-nibelungenlied", place_ids: ["de-worms-hagen"], location: "Adventure 1, stanza 6", location_zh: "第一歌第 6 节", text_orig: "In Worms am Rheine wohnten die Herrn in ihrer Kraft.\nVon ihren Landen diente viel stolze Ritterschaft", highlight_orig: ["Worms am Rheine"], text_en: "At Worms, by the Rhine, they dwelled in might with many a proud lord for vassal.", highlight_en: ["Worms, by the Rhine"], text_zh: "他们住在莱茵河畔的沃尔姆斯，威势赫赫，\n许多骄傲的骑士从他们的领地前来效命。", highlight_zh: ["莱茵河畔的沃尔姆斯"], translation: "Margaret Armour (1897)", status: "draft", checked: "Project Gutenberg #14915 and #3636, 2026-11-17" },
  { id: "de-sc7-s1", kind: "scene", book_id: "the-seventh-cross", place_ids: ["de-osthofen"], location: "Chapter 1", location_zh: "第 1 章", text_en: "In the autumn of 1937 seven prisoners break out of the Westhofen concentration camp near the Rhine. The commandant has seven plane trees cut into crosses to tie them to once they are caught; the others are caught or killed one by one, but George Heisler gets away, and the seventh cross stays empty.", text_zh: "1937 年秋，七个囚犯从莱茵河边的韦斯特霍芬集中营越狱。营长叫人把七棵梧桐树砍成十字架，抓回一个就绑上一个；其他人一个个被抓回或死去，只有格奥尔格·海斯勒逃脱了，第七个十字架一直空着。", highlight_en: ["the Westhofen concentration camp"], highlight_zh: ["韦斯特霍芬集中营"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Seventh_Cross" },
  { id: "de-kr-s1", kind: "scene", book_id: "krabat", place_ids: ["de-krabat-mill"], location: "The first year", location_zh: "第一年", text_en: "Krabat, a fourteen-year-old beggar boy, dreams three nights running of eleven ravens and a voice calling him to come to the mill at Schwarzkollm. He follows it to a mill hidden in the Koselbruch marsh, where the master takes him on as the twelfth apprentice and teaches him black magic.", text_zh: "十四岁的乞丐少年克拉巴特一连三夜梦见十一只乌鸦，还有一个声音叫他到施瓦茨科尔姆的磨坊去。他循着声音来到藏在科瑟尔沼泽里的磨坊，磨坊主收他当了第十二个学徒，教他黑魔法。", highlight_en: ["the mill at Schwarzkollm"], highlight_zh: ["施瓦茨科尔姆的磨坊"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Krabat_(novel)" },
  { id: "de-tow-s1", kind: "scene", book_id: "the-tower", place_ids: ["de-weisser-hirsch"], location: "Book 1", location_zh: "第一部", text_en: "In the villa quarter on the slopes above the Elbe that its residents call 'the Tower', families of doctors and publishers keep up their music evenings and old books in the 1980s as if East Germany were not outside the door; the schoolboy Christian Hoffmann grows up among them before the army and the autumn of 1989.", text_zh: "易北河上方山坡的别墅区被住户们叫作“塔”。八十年代，这里的医生和出版人家庭照样开音乐晚会、守着旧书，好像门外不是民主德国；中学生克里斯蒂安·霍夫曼就在他们中间长大，然后去当兵，迎来 1989 年秋天。", highlight_en: ["the villa quarter on the slopes above the Elbe"], highlight_zh: ["易北河上方山坡的别墅区"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Tower_(Tellkamp_novel)" },
  { id: "de-tsc-s1", kind: "scene", book_id: "why-we-took-the-car", place_ids: ["de-marzahn"], location: "Chapters 1–15", location_zh: "第 1–15 章", text_en: "Maik Klingenberg, fourteen, lives in a villa in Marzahn and is the class nobody. When his mother goes off to rehab and his father off with his assistant, he is left alone for the summer, until Tschick, the new boy from Russia, turns up in a stolen Lada and they set off with no map.", text_zh: "十四岁的迈克·克林根贝格住在马灿的一座别墅里，在班上没人理。妈妈去戒酒、爸爸带着女助理出门，暑假里只剩他一个人，直到俄罗斯来的转学生契克开着一辆偷来的拉达出现，两人不带地图就上路了。", highlight_en: ["Marzahn"], highlight_zh: ["马灿"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Why_We_Took_the_Car" },
  { id: "de-her-s1", kind: "scene", book_id: "where-you-come-from", place_ids: ["de-emmertsgrund"], location: "Emmertsgrund", location_zh: "《埃默茨格伦德》", text_en: "Arriving in Heidelberg at fourteen as a refugee from Bosnia, the narrator ends up in Emmertsgrund, a hillside estate of high-rises full of other newcomers, where the place that does most for integration is a run-down Aral petrol station.", text_zh: "十四岁的叙述者作为波黑难民来到海德堡，落脚在山坡上满是外来户的高楼区埃默茨格伦德；在这里，最出力帮人融入的地方是一座破旧的阿拉尔加油站。", highlight_en: ["Emmertsgrund"], highlight_zh: ["埃默茨格伦德"], status: "draft", fact_source: "https://www.freitag.de/autoren/konstantin-ulmer/katze-sprich" },
  { id: "de-bt-s1", kind: "scene", book_id: "the-book-thief", place_ids: ["de-dachau"], location: "The march to Dachau", location_zh: "去达豪的队伍", text_en: "A column of Jewish prisoners is marched through Molching on the way to Dachau. Hans Hubermann steps out of the crowd and gives an old man a piece of bread; a soldier whips them both, and Hans fears that he has put the Jew hidden in his basement in danger.", text_zh: "一队犹太囚犯被押着穿过莫尔兴镇，往达豪去。汉斯·胡伯曼从人群里走出来，递给一个老人一块面包；士兵把两人都抽了鞭子，汉斯开始担心自己连累了藏在地下室里的那个犹太人。", highlight_en: ["Dachau"], highlight_zh: ["达豪"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Book_Thief" },
  { id: "de-spy-s1", kind: "scene", book_id: "the-spy-who-came-in-from-the-cold", place_ids: ["de-checkpoint-charlie"], location: "Chapter 1", location_zh: "第 1 章", text_en: "Alec Leamas waits through the night at the checkpoint for Karl Riemeck, his last agent in the East, to come across. Riemeck rides up on a bicycle, the searchlights catch him, and he is shot down a few yards short of the West.", text_zh: "利玛斯在检查站等了一整夜，等他在东边的最后一名特工卡尔·里梅克过来。里梅克骑着自行车来了，被探照灯照住，离西边只差几码就被打死了。", highlight_en: ["the checkpoint"], highlight_zh: ["检查站"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Spy_Who_Came_in_from_the_Cold" },
  { id: "de-clo-s1", kind: "scene", book_id: "the-clown", place_ids: ["de-bonn-hbf"], location: "The ending", location_zh: "结尾", text_en: "With nothing left, Hans Schnier paints his face white, takes his guitar and a cushion and sits on the steps of Bonn station among the Carnival crowds, singing and holding out his hat, while he waits for Marie's train from Rome.", text_zh: "一无所有的汉斯·施尼尔抹上白脸，带着吉他和一个坐垫，坐在狂欢节人群中的波恩火车站台阶上，一边唱歌一边伸着帽子讨钱，等着玛丽从罗马坐火车回来。", highlight_en: ["Bonn station"], highlight_zh: ["波恩火车站"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Clown_(novel)" },
  { id: "de-obe-s1", kind: "scene", book_id: "the-black-obelisk", place_ids: ["de-remarque-osnabrueck"], location: "Chapter 1", location_zh: "第 1 章", text_en: "In 1923, as inflation makes money worthless by the hour, the twenty-five-year-old Ludwig Bodmer sells gravestones for a monument firm in the small town of Werdenbrück; the black obelisk in the yard, too ugly for anyone to buy, becomes the joke and the emblem of the times.", text_zh: "1923 年通货膨胀，钱一个钟头一个价，二十五岁的路德维希·博德默在小城维尔登布吕克替一家墓碑公司卖墓碑；院子里那块丑得没人买的黑色方尖碑，成了那个时代的笑话，也成了它的象征。", highlight_en: ["Werdenbrück"], highlight_zh: ["维尔登布吕克"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Black_Obelisk" },
  { id: "de-fr-2", book_id: "frankenstein", place_ids: ["de-ingolstadt-anatomy"], location: "Chapter 5", location_zh: "第 5 章", text_en: "It was on a dreary night of November that I beheld the accomplishment of my toils. With an anxiety that almost amounted to agony, I collected the instruments of life around me, that I might infuse a spark of being into the lifeless thing that lay at my feet. It was already one in the morning; the rain pattered dismally against the panes, and my candle was nearly burnt out, when, by the glimmer of the half-extinguished light, I saw the dull yellow eye of the creature open; it breathed hard, and a convulsive motion agitated its limbs. … Morning, dismal and wet, at length dawned and discovered to my sleepless and aching eyes the church of Ingolstadt, its white steeple and clock, which indicated the sixth hour.", highlight_en: ["Ingolstadt"], text_zh: "那是十一月一个阴沉的夜晚，我终于看到了自己辛劳的成果。我焦虑得几近痛苦，把赋予生命的器具收拢在身边，好往躺在脚下的那具没有生命的东西里注入一星生命的火花。已经是凌晨一点了；雨点凄凉地打着窗玻璃，我的蜡烛也快燃尽了。就在这将灭未灭的微光里，我看见那造物昏黄的眼睛睁开了；它粗重地喘着气，四肢一阵痉挛。…… 阴冷潮湿的早晨终于来了，我那失眠而酸痛的眼睛看见了因戈尔施塔特的教堂，白色的尖塔和钟，时针指着六点。", highlight_zh: ["因戈尔施塔特"], translation: "original", status: "draft", checked: "Project Gutenberg #84, 2026-11-17" },
  // —— 11-23: second pack (tools/content/batches/add_de1.py) ——
  { id: "de-wn-1", book_id: "wanderers-nachtlied", place_ids: ["de-kickelhahn"], location: "The whole poem", location_zh: "全诗", text_orig: "Ueber allen Gipfeln\nIst Ruh’,\nIn allen Wipfeln\nSpürest du\nKaum einen Hauch;\nDie Vögelein schweigen im Walde.\nWarte nur, balde\nRuhest du auch.", highlight_orig: ["allen Gipfeln"], text_en: "Over all the hilltops\nis peace,\nin all the treetops\nyou feel\nhardly a breath;\nthe little birds are silent in the wood.\nOnly wait: soon\nyou too will rest.", highlight_en: ["all the hilltops"], text_zh: "群峰之巅\n一片寂静，\n所有的树梢上\n你几乎\n感觉不到一丝风；\n林中的小鸟默默无声。\n且等着，不久\n你也将安息。", highlight_zh: ["群峰之巅"], translation: "own", status: "draft", checked: "German Wikisource, Ein Gleiches, 2026-11-23" },
  { id: "de-hd-1", book_id: "an-heidelberg", place_ids: ["de-heidelberg-old-bridge"], location: "Stanzas 1–2", location_zh: "第一、二节", text_orig: "Lange lieb’ ich dich schon, möchte dich, mir zur Lust,\nMutter nennen und dir schenken ein kunstlos Lied,\nDu, der Vaterlandsstädte,\nLändlich schönste, so viel’ ich sah!\nWie der Vogel des Walds über die Gipfel fliegt,\nSchwingt sich über den Strom, wo er vorbei dir glänzt,\nLeicht und kräftig die Brücke,\nDie von Wagen und Menschen tönt.", highlight_orig: ["die Brücke"], text_en: "Long have I loved you, and would, for my own delight,\ncall you mother and give you an artless song,\nyou, of all my country's towns\nthe loveliest in its setting that I have seen.\nAs the bird of the forest flies over the peaks,\nso over the river, where it gleams past you,\nswings light and strong the bridge\nthat rings with wagons and people.", highlight_en: ["the bridge"], text_zh: "我爱你已久，为了自己高兴，\n真想叫你一声母亲，献给你一首朴拙的歌，\n你啊，在我见过的祖国城市里，\n风光最美的一座！\n像林中的鸟飞越山巅，\n在那条从你身旁闪光流过的河上，\n轻盈而有力地飞架着那座桥，\n车马行人在桥上喧响。", highlight_zh: ["那座桥"], translation: "own", status: "draft", checked: "German Wikisource, An Heidelberg, 2026-11-23" },
  { id: "de-wm-k1", book_id: "germany-a-winters-tale", place_ids: ["de-cologne-cathedral"], location: "Caput IV", location_zh: "第四章", text_orig: "Doch siehe! dort im Mondenschein\nDen kolossalen Gesellen!\nEr ragt verteufelt schwarz empor,\nDas ist der Dom von Cöllen.\nEr sollte des Geistes Bastille sein,\nUnd die listigen Römlinge dachten:\nIn diesem Riesenkerker wird\nDie deutsche Vernunft verschmachten!", highlight_orig: ["Dom von Cöllen"], text_en: "But look! There in the moonlight,\nthat colossal fellow!\nHe looms up devilishly black:\nthat is the cathedral of Cologne.\nIt was meant to be the Bastille of the spirit,\nand the cunning Romanists thought:\nin this gigantic dungeon\nGerman reason will pine away!", highlight_en: ["cathedral of Cologne"], text_zh: "可是看哪！月光下\n那个庞然大物！\n它黑得像魔鬼一样耸立着，\n那就是科隆大教堂。\n它本该成为精神的巴士底狱，\n狡猾的罗马信徒们想：\n在这座巨大的牢狱里，\n德意志的理性将会憔悴而死！", highlight_zh: ["科隆大教堂"], translation: "own", status: "draft", checked: "German Wikisource, Deutschland. Ein Wintermährchen, 2026-11-23" },
  { id: "de-wm-ky1", book_id: "germany-a-winters-tale", place_ids: ["de-kyffhaeuser"], location: "Caput XIV", location_zh: "第十四章", text_orig: "Sie hat mir versichert, er sey nicht todt,\nWie da glauben die Gelehrten,\nEr hause versteckt in einem Berg\nMit seinen Waffengefährten.\nKiffhäuser ist der Berg genannt,\nUnd drinnen ist eine Höhle;\nDie Ampeln erhellen so geisterhaft\nDie hochgewölbten Sääle.", highlight_orig: ["Kiffhäuser"], text_en: "She assured me he was not dead,\nas the scholars believe;\nhe lives hidden in a mountain\nwith his companions in arms.\nKyffhäuser is the mountain's name,\nand inside it is a cavern;\nthe lamps light up so ghostly\nthe high-vaulted halls.", highlight_en: ["Kyffhäuser"], text_zh: "她向我保证，他并没有死，\n不像学者们以为的那样；\n他藏身在一座山里，\n同他的战友们住在一起。\n那座山名叫屈夫霍伊泽，\n山里有一个洞窟；\n灯盏幽幽地照亮\n那些穹顶高耸的大厅。", highlight_zh: ["屈夫霍伊泽"], translation: "own", status: "draft", checked: "German Wikisource, Deutschland. Ein Wintermährchen, 2026-11-23" },
  { id: "de-gz-1", book_id: "goetz-von-berlichingen", place_ids: ["de-jagsthausen"], location: "Act 1, 'Jaxthausen. Götz's castle'", location_zh: "第一幕“雅克斯特豪森·葛兹的城堡”", text_orig: "Karl. Jaxthausen ist ein Dorf und Schloß an der Jaxt, gehört seit zweihundert Jahren den Herrn von Berlichingen erb- und eigenthümlich zu.\nGötz. Kennst du den Herrn von Berlichingen?\nKarl sieht ihn starr an.", highlight_orig: ["Jaxthausen"], text_en: "KARL. Jaxthausen is a village and castle on the Jaxt, and has belonged for two hundred years to the lords of Berlichingen by inheritance and in their own right.\nGÖTZ. Do you know the lord of Berlichingen?\nKarl stares at him.", highlight_en: ["Jaxthausen"], text_zh: "卡尔：雅克斯特豪森是雅克斯特河边的一个村子和一座城堡，两百年来世世代代归贝利欣根家的老爷们所有。\n葛兹：你认识贝利欣根老爷吗？\n卡尔呆呆地看着他。", highlight_zh: ["雅克斯特豪森"], translation: "own", status: "draft", checked: "German Wikisource, Götz von Berlichingen mit der eisernen Hand, 2026-11-23" },
  { id: "de-gt-1", book_id: "the-golden-pot", place_ids: ["de-dresden-albertplatz"], location: "First Vigil", location_zh: "第一夜", text_orig: "Am Himmelfahrtstage, Nachmittags um drei Uhr, rannte ein junger Mensch in Dresden durchs Schwarze Thor, und geradezu in einen Korb mit Aepfeln und Kuchen hinein, die ein altes häßliches Weib feil bot, so, daß Alles, was der Quetschung glücklich entgangen, hinausgeschleudert wurde, und die Straßenjungen sich lustig in die Beute theilten, die ihnen der hastige Herr zugeworfen.", highlight_orig: ["Schwarze Thor"], text_en: "On Ascension Day, at three in the afternoon, a young man ran through the Black Gate in Dresden and straight into a basket of apples and cakes that an ugly old woman was offering for sale, so that everything that had happily escaped being crushed was flung out, and the street urchins merrily shared the booty the hasty gentleman had thrown them.", highlight_en: ["Black Gate"], text_zh: "升天节那天下午三点钟，一个年轻人在德累斯顿跑过黑门，一头撞进一个丑老太婆摆着卖的一篮苹果和糕饼里，没被压烂的全给撞飞了出去，街上的顽童们高高兴兴地分掉了这位冒失先生抛给他们的战利品。", highlight_zh: ["黑门"], translation: "own", status: "draft", checked: "German Wikisource, Der goldne Topf, 2026-11-23" },
  { id: "de-at-1", book_id: "am-turme", place_ids: ["de-meersburg"], location: "Stanza 1", location_zh: "第一节", text_orig: "Ich steh’ auf hohem Balkone am Thurm,\nUmstrichen vom schreienden Staare.\nUnd lass’ gleich einer Mänade den Sturm\nMir wühlen im flatternden Haare;\nO wilder Geselle, o toller Fant,\nIch möchte dich kräftig umschlingen\nUnd, Sehne an Sehne, zwei Schritte vom Rand\nAuf Tod und Leben dann ringen!", highlight_orig: ["Balkone am Thurm"], text_en: "I stand on the high balcony of the tower,\nthe shrieking starling sweeping round me,\nand like a maenad I let the storm\ntear at my streaming hair;\nO wild fellow, O mad young blade,\nI would throw my arms tight around you\nand, sinew to sinew, two steps from the edge,\nwrestle with you for life or death!", highlight_en: ["balcony of the tower"], text_zh: "我站在塔楼高高的阳台上，\n尖叫的椋鸟在身边掠过，\n我像酒神的女祭司，任凭风暴\n撕扯我飞扬的头发；\n啊，狂野的伙伴，疯癫的小子，\n我真想紧紧抱住你，\n筋骨相抵，离边缘两步，\n同你拼个你死我活！", highlight_zh: ["塔楼高高的阳台"], translation: "own", status: "draft", checked: "German Wikisource, Am Thurme, 2026-11-23" },
  { id: "de-ds-1", book_id: "die-stadt-storm", place_ids: ["de-storm-husum"], location: "The whole poem", location_zh: "全诗", text_orig: "Am grauen Strand, am grauen Meer\nUnd seitab liegt die Stadt;\nDer Nebel drückt die Dächer schwer,\nUnd durch die Stille braust das Meer\nEintönig um die Stadt.\nEs rauscht kein Wald, es schlägt im Mai\nKein Vogel ohn’ Unterlaß;\nDie Wandergans mit hartem Schrei\nNur fliegt in Herbstesnacht vorbei,\nAm Strande weht das Gras.\nDoch hängt mein ganzes Herz an dir,\nDu graue Stadt am Meer;\nDer Jugend Zauber für und für\nRuht lächelnd doch auf dir, auf dir,\nDu graue Stadt am Meer.", highlight_orig: ["graue Stadt am Meer"], text_en: "By the grey shore, by the grey sea,\nand off to one side, lies the town;\nthe fog weighs heavy on the roofs,\nand through the stillness the sea roars\nmonotonously round the town.\nNo forest rustles, no bird sings\nin May without a pause;\nonly the wild goose with its harsh cry\nflies past on autumn nights,\nand on the shore the grass blows.\nYet my whole heart clings to you,\nyou grey town by the sea;\nthe magic of youth for ever and ever\nrests smiling still on you, on you,\nyou grey town by the sea.", highlight_en: ["grey town by the sea"], text_zh: "在灰色的海滩，灰色的大海旁，\n偏在一边，坐落着这座城；\n雾沉沉地压着屋顶，\n大海穿过寂静，\n单调地绕城喧响。\n没有森林的涛声，五月里\n也没有鸟儿不停地歌唱；\n只有大雁带着刺耳的叫声\n在秋夜里飞过，\n海滩上野草飘荡。\n可我的整颗心都系在你身上，\n你这海边的灰色的城；\n青春的魔力永远永远\n仍微笑着留在你身上，你身上，\n你这海边的灰色的城。", highlight_zh: ["海边的灰色的城"], translation: "own", status: "draft", checked: "German Wikisource, Die Stadt (Storm), 2026-11-23" },
  { id: "de-rb-1", book_id: "herr-von-ribbeck", place_ids: ["de-ribbeck"], location: "Lines 1–10", location_zh: "第 1—10 行", text_orig: "Herr von Ribbeck auf Ribbeck im Havelland,\nEin Birnbaum in seinem Garten stand,\nUnd kam die goldene Herbsteszeit,\nUnd die Birnen leuchteten weit und breit,\nDa stopfte, wenn’s Mittag vom Thurme scholl,\nDer von Ribbeck sich beide Taschen voll,\nUnd kam in Pantinen ein Junge daher,\nSo rief er: „Junge, wist’ ne Beer?“\nUnd kam ein Mädel, so rief er: „Lütt Dirn,\nKumm man röwer, ick hebb’ ne Birn.“", highlight_orig: ["Ribbeck im Havelland"], text_en: "Squire von Ribbeck at Ribbeck in Havelland,\na pear tree in his garden stood,\nand when the golden autumn came\nand the pears shone far and wide,\nthen, when noon rang from the tower,\nvon Ribbeck stuffed both his pockets full,\nand if a boy came by in clogs\nhe called: 'Lad, d'you want a pear?'\nAnd if a girl came, he called: 'Little lass,\ncome over here, I've got a pear.'", highlight_en: ["Ribbeck in Havelland"], text_zh: "哈弗尔兰的里贝克村有位冯·里贝克老爷，\n他的园子里长着一棵梨树，\n每到金色的秋天，\n梨子四下里闪闪发亮，\n钟楼敲响正午的钟声，\n冯·里贝克就把两个口袋塞得满满，\n要是有个穿木屐的男孩走过，\n他就喊：“小子，要个梨不？”\n要是来了个女孩，他就喊：“小丫头，\n过来吧，我这儿有梨。”", highlight_zh: ["哈弗尔兰的里贝克村"], translation: "own", status: "draft", checked: "German Wikisource, Herr von Ribbeck auf Ribbeck im Havelland (Fontane), 2026-11-23" },
  { id: "de-jb-1", book_id: "the-jews-beech", place_ids: ["de-bellersen"], location: "Opening", location_zh: "开头", text_orig: "Friedrich Mergel, geboren 1738, war der einzige Sohn eines sogenannten Halbmeiers oder Grundeigenthümers geringerer Klasse im Dorfe B., das, so schlecht gebaut und rauchig es seyn mag, doch das Auge jedes Reisenden fesselt durch die überaus malerische Schönheit seiner Lage in der grünen Waldschlucht eines bedeutenden und geschichtlich merkwürdigen Gebirges.", highlight_orig: ["Dorfe B."], text_en: "Friedrich Mergel, born in 1738, was the only son of a so-called half-farmer, or landowner of the lower class, in the village of B., which, badly built and smoky as it may be, yet catches every traveller's eye by the extremely picturesque beauty of its position in the green wooded gorge of a considerable and historically notable range of hills.", highlight_en: ["village of B."], text_zh: "弗里德里希·梅格尔生于 1738 年，是 B 村一个所谓“半份农”即下等地主的独生子。这个村子尽管房屋简陋、烟熏火燎，却因为坐落在一条有名的、在历史上颇值得一提的山脉的绿色林谷里，景色格外如画，吸引着每一个过路人的目光。", highlight_zh: ["B 村"], translation: "own", status: "draft", checked: "German Wikisource, Die Judenbuche, 2026-11-23" },
  { id: "de-byron-1", book_id: "pt-childe-harold", place_ids: ["de-drachenfels"], location: "Canto III, the song after stanza 55", location_zh: "第三章第 55 节后的歌", text_en: "The castled Crag of Drachenfels\nFrowns o'er the wide and winding Rhine,\nWhose breast of waters broadly swells\nBetween the banks which bear the vine,\nAnd hills all rich with blossomed trees,\nAnd fields which promise corn and wine,\nAnd scattered cities crowning these,\nWhose far white walls along them shine,\nHave strewed a scene, which I should see\nWith double joy wert thou with me.", highlight_en: ["Drachenfels"], translation: "original", text_zh: "德拉亨费尔斯的峭壁上城堡高踞，\n俯视着宽阔蜿蜒的莱茵河，\n河水的胸膛浩荡地鼓起，\n两岸是结满葡萄的山坡，\n山丘上开满花的树木繁茂，\n田野预示着谷物和美酒，\n散落的城镇点缀其间，\n远处的白墙沿岸闪耀，\n铺展成一片风景——若有你在身旁，\n我看它时会加倍欢畅。", highlight_zh: ["德拉亨费尔斯"], status: "draft", checked: "English Wikisource, The Works of Lord Byron (ed. Coleridge, Prothero)/Poetry/Volume 2/Childe Harold's Pilgrimage/Canto III (the editor's note mark left out), 2026-11-23" },
  { id: "de-hz-s1", kind: "scene", book_id: "harzreise", place_ids: ["de-goettingen-rathaus"], location: "Opening", location_zh: "开头", text_en: "Heine begins his walking tour by taking leave of Göttingen: a town famous, he says, for its sausages and its university, whose inhabitants he sorts into students, professors, philistines and cattle. Then he shoulders his knapsack and sets out for the mountains.", text_zh: "海涅的徒步旅行从告别哥廷根写起：他说这座城以香肠和大学闻名，城里的居民可以分成大学生、教授、市侩和牲口四类。然后他背起行囊，向山里走去。", highlight_en: ["Göttingen"], highlight_zh: ["哥廷根"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Die_Harzreise" },
  { id: "de-ph-s1", kind: "scene", book_id: "prince-of-homburg", place_ids: ["de-fehrbellin"], location: "Acts 2 and 5", location_zh: "第二幕和第五幕", text_en: "The young prince, dreaming of glory, does not hear his orders, charges too soon at Fehrbellin and helps win the battle. The Elector has him court-martialled and condemned for disobedience, and only when the prince accepts the sentence as just is he pardoned.", text_zh: "年轻的亲王一心梦想荣誉，没有听清命令，在费尔贝林提前发起冲锋，帮着打赢了这一仗。选帝侯却把他交军事法庭，以抗命罪判了死刑；直到亲王自己承认判决公正，才得到赦免。", highlight_en: ["Fehrbellin"], highlight_zh: ["费尔贝林"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Prince_of_Homburg_(play)" },
  { id: "de-lw-s1", kind: "scene", book_id: "lotte-in-weimar", place_ids: ["de-hotel-elephant"], location: "Chapter 1", location_zh: "第一章", text_en: "One morning in September 1816 the mail coach sets down three women at the Elephant. The waiter Mager, reading the register, realises that the elderly lady from Hanover is Werther's Lotte, and before she has unpacked, half of Weimar is on its way to look at her.", text_zh: "1816 年 9 月的一个早晨，驿车在大象旅馆门前放下三位女客。茶房马格尔看了登记簿，认出这位从汉诺威来的老太太就是维特的绿蒂；她行李还没打开，半个魏玛城的人已经赶来看她了。", highlight_en: ["the Elephant"], highlight_zh: ["大象旅馆"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lotte_in_Weimar:_The_Beloved_Returns" },
  { id: "de-ng-s1", kind: "scene", book_id: "narcissus-and-goldmund", place_ids: ["de-maulbronn"], location: "Chapter 1", location_zh: "第一章", text_en: "The book begins with the old chestnut tree at the gate of the monastery of Mariabronn. The boy Goldmund is brought there by his father to become a monk and attaches himself to the young teacher Narcissus, who sees that his friend is made for the world outside and tells him so.", text_zh: "小说从玛利亚布隆修道院大门口那棵老栗子树写起。少年歌尔德蒙被父亲送来，准备将来当修士，他依恋上了年轻的教师纳尔齐斯；纳尔齐斯却看出这位朋友属于外面的世界，并把这话告诉了他。", highlight_en: ["Mariabronn"], highlight_zh: ["玛利亚布隆"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Narcissus_and_Goldmund" },
  { id: "de-be-s1", kind: "scene", book_id: "buckow-elegies", place_ids: ["de-buckow"], location: "The cycle", location_zh: "组诗", text_en: "Written in the weeks after the workers' rising of 17 June 1953, the poems are a few plain lines each: smoke from a house by the lake, a man waiting while his driver changes a wheel, the garden, the firs at dawn. The sharpest of them, on the government and the people, was not printed in East Germany in his lifetime.", text_zh: "这些诗写于 1953 年 6 月 17 日工人起义之后的几个星期，每首只有寥寥几行朴素的句子：湖边房子升起的炊烟，等着司机换车轮的人，花园，黎明时的冷杉。其中最尖锐的一首写的是政府与人民，在他生前没有在东德发表。", highlight_en: ["by the lake"], highlight_zh: ["湖边"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Buckower_Elegien" },
  { id: "de-rh-s1", kind: "scene", book_id: "rheinsberg", place_ids: ["de-rheinsberg"], location: "The whole story", location_zh: "全篇", text_en: "Claire and Wolfgang, not married and pretending to be, take the train from Berlin for three days in Rheinsberg. They row on the lake, are shown round the palace by a castellan, tease each other in Claire's private baby-talk, and go home. Almost nothing happens, and that lightness made the little book a bestseller.", text_zh: "克莱尔和沃尔夫冈没有结婚，却冒充夫妻，从柏林坐火车到莱茵斯贝格玩了三天。他们在湖上划船，由管理员领着参观宫殿，用克莱尔自创的娃娃腔互相打趣，然后回家。几乎什么事也没发生，而正是这份轻盈让这本小书成了畅销书。", highlight_en: ["Rheinsberg"], highlight_zh: ["莱茵斯贝格"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Rheinsberg:_Ein_Bilderbuch_für_Verliebte" },
  { id: "de-me-s1", kind: "scene", book_id: "mephisto", place_ids: ["de-gendarmenmarkt"], location: "The later chapters", location_zh: "后半部", text_en: "Hendrik Höfgen, a provincial actor with left-wing friends, makes his name playing Mephisto. When the Nazis come to power he lets the prime minister, a fat man who loves the theatre, become his patron, drops those who could compromise him, and ends as director of the State Theatre in Berlin.", text_zh: "亨德里克·赫夫根原是个结交左派朋友的外省演员，靠扮演梅菲斯特成名。纳粹上台后，他让那位爱看戏的胖总理当了自己的靠山，甩掉一切可能连累他的人，最后当上了柏林国家剧院的院长。", highlight_en: ["the State Theatre in Berlin"], highlight_zh: ["柏林国家剧院"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Mephisto_(novel)" },
  { id: "de-mo-s1", kind: "scene", book_id: "the-man-outside", place_ids: ["de-landungsbruecken"], location: "Prologue and 'The Dream'", location_zh: "序幕和“梦”", text_en: "Beckmann, a sergeant back from three years as a prisoner in Siberia with a stiff knee and gas-mask glasses, finds another man in his wife's bed and throws himself into the Elbe from a pontoon at St. Pauli. The river, an old woman who has no patience with him, spits him out again on the sand at Blankenese.", text_zh: "下士贝克曼在西伯利亚当了三年战俘，带着一条僵直的腿和一副防毒面具眼镜回到家，发现妻子床上躺着别的男人，就从圣保利的一座浮桥上跳进了易北河。易北河是个对他毫无耐心的老太婆，又把他吐回到布兰克内泽的沙滩上。", highlight_en: ["a pontoon at St. Pauli"], highlight_zh: ["圣保利的一座浮桥"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Man_Outside" },
  { id: "de-gl-s1", kind: "scene", book_id: "the-german-lesson", place_ids: ["de-seebuell"], location: "The essay Siggi writes", location_zh: "西吉写的那篇作文", text_en: "In 1943 the policeman of Rugbüll, the northernmost police post in Germany, is ordered to deliver a ban on painting to his neighbour and old friend, the painter Nansen, and to see that it is kept. His son Siggi, who hides the pictures, tells the story years later in a reformatory, set to write an essay on 'The Joys of Duty'.", text_zh: "1943 年，德国最北端的警察哨所鲁格比尔的警察奉命把一纸禁画令送给邻居兼老友、画家南森，并监督执行。他的儿子西吉把那些画藏了起来；多年后，西吉在少年教养所里被罚写一篇题为《尽职的快乐》的作文，讲出了这段往事。", highlight_en: ["Rugbüll"], highlight_zh: ["鲁格比尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_German_Lesson" },
  { id: "de-tt-s1", kind: "scene", book_id: "the-meeting-at-telgte", place_ids: ["de-telgte"], location: "The whole tale", location_zh: "全篇", text_en: "In the summer of 1647 the Königsberg poet Simon Dach calls the scattered poets of Germany together. Turned away from their first inn, they are quartered at the Bridge Inn in Telgte by a soldier called Gelnhausen, read their manuscripts to one another for three days and draft an appeal for peace. The inn burns down, and the appeal with it.", text_zh: "1647 年夏天，柯尼斯堡诗人西蒙·达赫把散居各地的德意志诗人召集到一起。第一家客栈不收留他们，一个名叫盖尔恩豪森的士兵把他们安顿在特尔格特的桥头客栈。他们互相朗读手稿三天，还起草了一份和平呼吁书。客栈起火烧毁，呼吁书也一同化为灰烬。", highlight_en: ["Telgte"], highlight_zh: ["特尔格特"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Meeting_at_Telgte" },
  { id: "de-dh-s1", kind: "scene", book_id: "divided-heaven", place_ids: ["de-halle"], location: "The whole novel", location_zh: "全书", text_en: "Rita Seidel, training to be a teacher, works in a brigade at the railway-carriage works; Manfred, the chemist she lives with, grows bitter when his invention is turned down. In the summer of 1961 he goes to West Berlin. She visits him once, comes back, and after the Wall is built she collapses between two moving wagons at the works.", text_zh: "正在读师范的丽塔·赛德尔在车辆厂的一个生产队里劳动；同她一起生活的化学家曼弗雷德因为发明被否决而日渐消沉。1961 年夏天，他去了西柏林。她去看过他一次，又回来了；柏林墙建起之后，她在厂里两节移动的车皮之间昏倒。", highlight_en: ["the railway-carriage works"], highlight_zh: ["车辆厂"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Der_geteilte_Himmel" },
  { id: "de-an-s1", kind: "scene", book_id: "anniversaries", place_ids: ["de-kluetz"], location: "The whole novel", location_zh: "全书", text_en: "Day by day from August 1967 to August 1968, Gesine Cresspahl, a bank employee on Riverside Drive in New York, reads the New York Times and tells her ten-year-old daughter Marie about the small Mecklenburg town of Jerichow: her father the cabinet-maker, the Nazi years, the Soviet occupation and the early GDR.", text_zh: "从 1967 年 8 月到 1968 年 8 月，一天接一天，住在纽约河滨大道的银行职员格西内·克雷斯帕尔读着《纽约时报》，给十岁的女儿玛丽讲梅克伦堡小城耶里肖的往事：做细木工的父亲，纳粹年代，苏军占领，还有民主德国的最初岁月。", highlight_en: ["Jerichow"], highlight_zh: ["耶里肖"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Anniversaries_(novel)" },
  { id: "de-vs-s1", kind: "scene", book_id: "vertigo-sebald", place_ids: ["de-wertach"], location: "Part 4, 'Il ritorno in patria'", location_zh: "第四部分《归乡》", text_en: "In November 1987 the narrator comes over the pass from Austria on foot and walks down through the gorge to W., the village he has not seen since childhood. He takes a room at the inn where his family once lived and goes over the people and houses of the place as they were when he was a boy.", text_zh: "1987 年 11 月，叙述者从奥地利徒步翻过山口，穿过峡谷走下来，回到自童年以后就没再见过的 W 村。他在全家当年住过的那家旅店里要了一个房间，把村里的人和房子按自己小时候的样子一一回想了一遍。", highlight_en: ["W."], highlight_zh: ["W 村"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Schwindel._Gefühle." },
  { id: "de-vi-s1", kind: "scene", book_id: "visitation", place_ids: ["de-scharmuetzelsee"], location: "The whole novel", location_zh: "全书", text_en: "A plot of land by a Brandenburg lake passes from a farmer's daughters to a Berlin architect, who builds a summer house on it. His Jewish neighbours sell up and are murdered; a young Red Army soldier is quartered in the house; a writer back from exile is given it by the state; her granddaughter loses it after 1990. Only the gardener is there through all of it.", text_zh: "勃兰登堡一个湖边的一块地，从农家女儿们手里转给了一位柏林建筑师，他在上面盖了一幢消夏别墅。他的犹太邻居卖掉产业后遭到杀害；一个年轻的红军士兵在房子里驻扎过；一位流亡归来的女作家从国家手里得到了它；1990 年以后，她的孙女又失去了它。自始至终都在的只有那个园丁。", highlight_en: ["a Brandenburg lake"], highlight_zh: ["勃兰登堡一个湖边"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Heimsuchung_(Roman)" },
  { id: "de-kr-s2", kind: "scene", book_id: "kruso", place_ids: ["de-hiddensee"], location: "The whole novel", location_zh: "全书", text_en: "In the summer of 1989 the student Ed, running from a loss, takes the ferry to Hiddensee and is hired as a dishwasher at the Klausner, an inn on the cliff. Its unofficial captain is Kruso, who shelters the 'shipwrecked' of the country, people who hope to swim for Denmark, and wants to teach them a freedom that needs no escape. By autumn the staff are leaving one by one for the opened border.", text_zh: "1989 年夏天，大学生埃德为了逃开失去亲近之人的痛苦，乘渡船来到希登塞岛，在崖上的克劳斯纳旅店当了洗碗工。旅店里不挂名的头领是克鲁索，他收留这个国家的“海难者”——那些指望游到丹麦去的人，想教给他们一种不必出逃的自由。到了秋天，店里的人一个接一个奔向已经打开的边境。", highlight_en: ["Hiddensee"], highlight_zh: ["希登塞岛"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Kruso" },
  { id: "de-sa-s1", kind: "scene", book_id: "sonnenallee", place_ids: ["de-sonnenallee"], location: "The whole novel", location_zh: "全书", text_en: "Micha Kuppisch and his friends are fifteen, live in the flats at the short end of the Sonnenallee, in sight of the western viewing platform, and are all in love with Miriam. Micha's first love letter from her is blown unread into the death strip, and most of the book is his campaign to get it back.", text_zh: "米夏·库皮施和他的朋友们十五岁，住在太阳大道较短那一头的公寓楼里，抬头就能看见西边的瞭望台，而且个个都爱着米丽亚姆。她写给米夏的第一封情书还没拆开就被风吹进了死亡地带，全书大半篇幅就是他想方设法要把信弄回来。", highlight_en: ["the short end of the Sonnenallee"], highlight_zh: ["太阳大道较短那一头"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Am_kürzeren_Ende_der_Sonnenallee" },
  { id: "de-sl-s1", kind: "scene", book_id: "stasiland", place_ids: ["de-runde-ecke"], location: "The Leipzig chapters", location_zh: "莱比锡部分", text_en: "Funder, an Australian working in Berlin in the 1990s, goes looking for people who resisted the Stasi and people who worked for it. In Leipzig she meets Miriam, who at sixteen was arrested for pasting up leaflets, got as far as the last fence of the Berlin Wall on her own, and is still trying to learn how her husband died in a Stasi cell.", text_zh: "澳大利亚人方德 1990 年代在柏林工作，开始寻访当年反抗过斯塔西的人和为斯塔西工作过的人。在莱比锡她见到了米丽亚姆：十六岁因张贴传单被捕，后来独自翻到了柏林墙的最后一道铁丝网前，如今仍在追查丈夫是怎样死在斯塔西牢房里的。", highlight_en: ["Leipzig"], highlight_zh: ["莱比锡"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Stasiland" },
  { id: "de-ch-s1", kind: "scene", book_id: "caspar-hauser", place_ids: ["de-ansbach"], location: "The Ansbach chapters", location_zh: "安斯巴赫部分", text_en: "Passed from one guardian to the next, the gentle foundling is brought to Ansbach and put in the house of the pedantic schoolmaster Quandt, who is set on proving him a fraud. Lured into the court garden on a snowy December afternoon by a stranger who promises news of his mother, he is stabbed, and even on his deathbed is not believed.", text_zh: "这个温顺的弃儿从一个监护人手里转到另一个监护人手里，最后被带到安斯巴赫，安置在迂腐的教师克万特家里，而克万特一心要证明他是个骗子。十二月一个下雪的下午，一个陌生人谎称有他母亲的消息，把他骗进宫廷花园，刺了他一刀；直到临终，人们还是不相信他。", highlight_en: ["Ansbach", "the court garden"], highlight_zh: ["安斯巴赫", "宫廷花园"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Caspar_Hauser_oder_Die_Trägheit_des_Herzens" },
  { id: "de-nw-s1", kind: "scene", book_id: "naked-among-wolves", place_ids: ["de-buchenwald"], location: "The whole novel", location_zh: "全书", text_en: "Early in 1945 a Polish prisoner arrives at Buchenwald with a three-year-old Jewish boy hidden in his suitcase. The prisoners of the storeroom hide the child, moving him from hut to hut while the SS search, although every hiding place puts the camp's secret resistance and its plans for a rising at risk.", text_zh: "1945 年初，一个波兰囚犯带着藏在手提箱里的三岁犹太男孩来到布痕瓦尔德。储藏室的囚犯们把孩子藏了起来，在党卫军搜查时把他从一个棚屋转移到另一个棚屋，尽管每一个藏身之处都会危及营里的秘密抵抗组织和起义计划。", highlight_en: ["Buchenwald"], highlight_zh: ["布痕瓦尔德"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Naked_Among_Wolves_(novel)" },
  { id: "de-gd-s1", kind: "scene", book_id: "gladius-dei", place_ids: ["de-odeonsplatz"], location: "The whole story", location_zh: "全篇", text_en: "On a brilliant June day a gaunt young man in a hooded cloak, Hieronymus, walks down from Schwabing through the cheerful crowds. In the window of a fine-art dealer's by Odeonsplatz hangs the reproduction of a sensual Madonna that the whole town admires. He goes in and demands that it be burned, and the packer throws him out into the square.", text_zh: "六月里阳光灿烂的一天，瘦削的年轻人希罗尼穆斯披着带兜帽的斗篷，从施瓦宾区穿过欢快的人群走来。音乐厅广场旁一家艺术品商店的橱窗里挂着一幅肉感的圣母像的复制品，全城人都在赞赏。他走进去，要求把它烧掉，结果被店里的打包工扔到了广场上。", highlight_en: ["Odeonsplatz"], highlight_zh: ["音乐厅广场"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Gladius_Dei" },
  { id: "de-cf-s1", kind: "scene", book_id: "christiane-f", place_ids: ["de-bahnhof-zoo"], location: "The whole book", location_zh: "全书", text_en: "Christiane grows up in the tower blocks of Gropiusstadt, starts on pills and hashish at twelve at a church youth club, and at fourteen is injecting heroin and earning the money for it around Bahnhof Zoo, where her friends are dying one after another. Two reporters from Stern recorded her account, and the book came out in 1978.", text_zh: "克里斯蒂安娜在格罗皮乌斯城的高楼群里长大，十二岁在教会的青少年活动中心开始接触药片和大麻，十四岁已经在注射海洛因，并在动物园火车站一带挣买毒品的钱，身边的朋友一个接一个地死去。《明星》周刊的两名记者记录下了她的讲述，书在 1978 年出版。", highlight_en: ["Bahnhof Zoo"], highlight_zh: ["动物园火车站"], status: "draft", fact_source: "https://de.wikipedia.org/wiki/Wir_Kinder_vom_Bahnhof_Zoo" }
];
